import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { format } from 'prettier';

const source = new URL('../Docs/driving-parameters.json', import.meta.url);
const destination = new URL('../src/profiles/parameter-catalog.generated.ts', import.meta.url);

export async function renderParameterCatalog() {
  const catalog = JSON.parse(await readFile(source, 'utf8'));
  return format(
    '// Generated by scripts/generate-parameter-catalog.mjs. Do not edit.\n' +
      `export const parameterCatalogData = ${JSON.stringify(catalog)} as const;\n`,
    {
      parser: 'typescript',
      ...JSON.parse(await readFile(new URL('../.prettierrc.json', import.meta.url), 'utf8')),
    },
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const rendered = await renderParameterCatalog();
  if (process.argv.includes('--check')) {
    if ((await readFile(destination, 'utf8')) !== rendered) {
      throw new Error(
        'Parameter catalog is stale. Run node scripts/generate-parameter-catalog.mjs',
      );
    }
    console.log('Parameter catalog is synchronized.');
  } else {
    await writeFile(destination, rendered);
    console.log('Generated parameter catalog.');
  }
}
